from dataclasses import dataclass
from typing import Protocol

class Notifier(Protocol):
    def send(self, message: str) -> bool: ...

@dataclass(frozen=True, slots=True)
class Alert:
    severity: str
    message: str

    def __post_init__(self) -> None:
        if self.severity not in {"INFO", "WARNING", "CRITICAL"}:
            raise ValueError(f"Sévérité inconnue: {self.severity}")

def dispatch(alert: Alert, notifier: Notifier) -> bool:
    if alert.severity == "CRITICAL" and not notifier.send(alert.message):
        raise RuntimeError("Échec d'envoi d'une alerte critique")
    return True
